  "source": "def investigate(context, acquire):
    actions = context.get('actions')
    if actions is None:
        actions = []
    sqlite = acquire('sqlite')
    connection = sqlite.connect(':memory:')
    cursor = connection.cursor()
    cursor.execute('CREATE TABLE t (id INTEGER PRIMARY KEY AUTOINCREMENT)')
    for action in actions:
        operation = action.get('op')
        if operation == 'put':
            cursor.execute('INSERT INTO t (id) VALUES (?)', (action.get('id'),))
        elif operation == 'delete':
            cursor.execute('DELETE FROM t WHERE id = ?', (action.get('id'),))
        elif operation == 'begin':
            cursor.execute('BEGIN')
        elif operation == 'commit':
            cursor.execute('COMMIT')
        elif operation == 'rollback':
            cursor.execute('ROLLBACK')
    cursor.execute('INSERT INTO t DEFAULT VALUES')
    result = cursor.execute('SELECT last_insert_rowid()').fetchone()[0]
    connection.close()
    return int(result)",
  "scope": "Repairs the native SQLite AUTOINCREMENT diagnostic while preserving the schema, action semantics, single connection, transaction handling, and final implicit insert. The only behavioral change is how the allocated rowid is read.",
  "change": "Replaced the unsupported cursor.lastrowid access with SELECT last_insert_rowid() on the same connection immediately after the final INSERT. This returns the AUTOINCREMENT-allocated integer, including persistence of sqlite_sequence across commit/rollback and the boundary case where id 1000 yields 1001."
